-- Brightline Logistics Pvt Ltd - finance test database (FICTIONAL company, fictional people, fake GSTIN/PAN/bank numbers).
-- Covers 2026-07-01 to 2026-11-12 (treat 2026-11-12 as 'today'). Fiscal year 2026-27. Amounts in INR.
-- Contains the business tables (customers, orders, shipments...) plus finance tables for 12 finance roles.
-- Planted test cases and expected results: see table test_scenarios.
-- Simplifications: all services taxed at 18% GST; opening receivables/payables at 1-Jul are zero.

BEGIN;

DROP TABLE IF EXISTS test_scenarios, erp_access_log, audit_findings, risk_register, kyc_records, customer_financials, credit_applications, employee_advances, expense_claims, payslips, payroll_runs, attendance_monthly, loan_schedule, loans, asset_depreciation, fixed_assets, tax_notices, compliance_calendar, form16a_received, form26as_entries, tds_certificates_issued, tds_returns, tds_challans, gst_returns, gstr2b_entries, vendor_statements, vendor_payments, vendor_invoice_lines, vendor_invoices, grn_lines, goods_receipts, po_lines, purchase_orders, vendor_bank_changes, vendors, driver_daily_logs, eway_bills, shipment_finance, insurance_claims, refunds, collection_activities, payment_promises, cod_collections, cod_deposits, gateway_settlement_items, gateway_settlements, receipt_allocations, receipts, credit_notes, invoice_lines, invoices, customer_credit_profiles, contracts, bank_transactions, bank_accounts, budgets, month_end_close_tasks, journal_lines, journal_entries, accounting_periods, approvals, approval_matrix, cost_centres, chart_of_accounts, finance_policies, employees, support_tickets, shipments, order_items, orders, drivers, products, customers, invoices CASCADE;

CREATE TABLE customers (
  customer_id int PRIMARY KEY,
  name varchar,
  customer_type varchar,
  email varchar,
  phone varchar,
  city varchar,
  region varchar,
  state varchar,
  state_code varchar,
  pan varchar,
  gstin varchar,
  created_at timestamptz
);
CREATE TABLE products (
  product_id int PRIMARY KEY,
  name varchar,
  category varchar,
  unit_price_inr numeric(14,2),
  stock_qty int,
  reorder_level int
);
CREATE TABLE drivers (
  driver_id int PRIMARY KEY,
  name varchar,
  phone varchar,
  base_city varchar,
  vehicle_type varchar,
  vehicle_no varchar,
  rating numeric(2,1),
  is_active boolean,
  joined_on date
);
CREATE TABLE orders (
  order_id varchar PRIMARY KEY,
  customer_id int REFERENCES customers,
  order_date timestamptz,
  origin_city varchar,
  destination_city varchar,
  destination_region varchar,
  status varchar,
  subtotal_inr numeric(14,2),
  gst_inr numeric(14,2),
  total_inr numeric(14,2),
  promised_by timestamptz,
  payment_method varchar
);
CREATE TABLE order_items (
  item_id int PRIMARY KEY,
  order_id varchar REFERENCES orders,
  product_id int REFERENCES products,
  quantity int,
  unit_price_inr numeric(14,2),
  line_total_inr numeric(14,2)
);
CREATE TABLE shipments (
  shipment_id int PRIMARY KEY,
  order_id varchar REFERENCES orders,
  driver_id int REFERENCES drivers,
  tracking_no varchar,
  current_status varchar,
  current_location varchar,
  eta timestamptz,
  delivered_at timestamptz,
  delay_reason varchar,
  damaged boolean
);
CREATE TABLE support_tickets (
  ticket_id varchar PRIMARY KEY,
  customer_id int REFERENCES customers,
  order_id varchar REFERENCES orders,
  category varchar,
  priority varchar,
  subject varchar,
  body text,
  status varchar,
  assigned_to varchar,
  created_at timestamptz,
  resolved_at timestamptz,
  csat int
);
CREATE TABLE employees (
  employee_id varchar PRIMARY KEY,
  name varchar,
  email varchar,
  department varchar,
  designation varchar,
  finance_role varchar,
  manager_id varchar,
  cost_centre varchar,
  joining_date date,
  exit_date date,
  status varchar,
  pan varchar,
  bank_account_no varchar,
  ifsc varchar,
  monthly_gross numeric(14,2),
  basic numeric(14,2),
  hra numeric(14,2),
  special_allowance numeric(14,2),
  pf_applicable boolean,
  esi_applicable boolean,
  overtime_eligible boolean,
  driver_id int REFERENCES drivers
);
CREATE TABLE finance_policies (
  policy_key varchar PRIMARY KEY,
  policy_value text,
  description text
);
CREATE TABLE chart_of_accounts (
  account_code varchar PRIMARY KEY,
  account_name varchar,
  account_type varchar,
  sub_type varchar,
  is_active boolean
);
CREATE TABLE cost_centres (
  cost_centre varchar PRIMARY KEY,
  name varchar,
  owner_employee_id varchar REFERENCES employees
);
CREATE TABLE approval_matrix (
  rule_id int PRIMARY KEY,
  document_type varchar,
  approver_role varchar,
  max_amount_inr numeric(14,2),
  rule text
);
CREATE TABLE approvals (
  approval_id int PRIMARY KEY,
  document_type varchar,
  document_id varchar,
  amount_inr numeric(14,2),
  requested_by varchar REFERENCES employees,
  approved_by varchar REFERENCES employees,
  approved_at timestamptz,
  status varchar,
  comments text
);
CREATE TABLE accounting_periods (
  period varchar PRIMARY KEY,
  status varchar,
  closed_on date,
  closed_by varchar REFERENCES employees
);
CREATE TABLE journal_entries (
  je_id int PRIMARY KEY,
  je_number varchar,
  je_date date,
  period varchar,
  je_type varchar,
  narration text,
  source_type varchar,
  source_id varchar,
  created_by varchar REFERENCES employees,
  created_at timestamptz,
  approved_by varchar REFERENCES employees,
  approved_at timestamptz,
  status varchar,
  has_attachment boolean
);
CREATE TABLE journal_lines (
  line_id int PRIMARY KEY,
  je_id int REFERENCES journal_entries,
  account_code varchar REFERENCES chart_of_accounts,
  debit numeric(14,2),
  credit numeric(14,2),
  cost_centre varchar,
  party_type varchar,
  party_id varchar
);
CREATE TABLE month_end_close_tasks (
  task_id int PRIMARY KEY,
  period varchar,
  task varchar,
  owner_employee_id varchar REFERENCES employees,
  due_date date,
  status varchar,
  completed_on date
);
CREATE TABLE budgets (
  budget_id int PRIMARY KEY,
  fiscal_year varchar,
  period varchar,
  account_code varchar REFERENCES chart_of_accounts,
  amount_inr numeric(14,2)
);
CREATE TABLE bank_accounts (
  bank_account_id int PRIMARY KEY,
  bank_name varchar,
  branch varchar,
  account_no_masked varchar,
  ifsc varchar,
  account_type varchar,
  purpose varchar,
  gl_account varchar,
  opening_balance_inr numeric(14,2),
  opening_date date,
  od_limit_inr numeric(14,2),
  interest_rate_pct numeric(5,2),
  maturity_date date,
  min_balance_alert_inr numeric(14,2)
);
CREATE TABLE bank_transactions (
  txn_id int PRIMARY KEY,
  bank_account_id int REFERENCES bank_accounts,
  txn_date date,
  value_date date,
  description varchar,
  reference varchar,
  debit_inr numeric(14,2),
  credit_inr numeric(14,2),
  balance_inr numeric(14,2)
);
CREATE TABLE contracts (
  contract_id int PRIMARY KEY,
  customer_id int REFERENCES customers,
  contract_no varchar,
  start_date date,
  end_date date,
  services varchar,
  pallets_reserved int,
  rate_per_pallet_inr numeric(14,2),
  monthly_freight_fee_inr numeric(14,2),
  billing_cycle varchar,
  payment_terms_days int,
  status varchar,
  signed_by varchar
);
CREATE TABLE customer_credit_profiles (
  customer_id int PRIMARY KEY REFERENCES customers,
  credit_limit_inr numeric(14,2),
  payment_terms_days int,
  risk_rating varchar,
  on_hold boolean,
  on_hold_since date,
  security_deposit_inr numeric(14,2),
  credit_check_done boolean,
  last_reviewed_on date,
  approved_by varchar
);
CREATE TABLE invoices (
  invoice_id varchar PRIMARY KEY,
  invoice_type varchar,
  order_id varchar REFERENCES orders,
  contract_id int REFERENCES contracts,
  customer_id int REFERENCES customers,
  issued_on date,
  due_on date,
  place_of_supply varchar,
  subtotal_inr numeric(14,2),
  cgst_inr numeric(14,2),
  sgst_inr numeric(14,2),
  igst_inr numeric(14,2),
  amount_inr numeric(14,2),
  irn varchar,
  irn_generated_on date,
  status varchar,
  created_by varchar
);
CREATE TABLE invoice_lines (
  line_id int PRIMARY KEY,
  invoice_id varchar REFERENCES invoices,
  line_no int,
  description varchar,
  product_id int REFERENCES products,
  quantity numeric(14,2),
  rate_inr numeric(14,2),
  amount_inr numeric(14,2),
  revenue_account varchar
);
CREATE TABLE credit_notes (
  credit_note_id varchar PRIMARY KEY,
  invoice_id varchar REFERENCES invoices,
  customer_id int REFERENCES customers,
  issued_on date,
  subtotal_inr numeric(14,2),
  cgst_inr numeric(14,2),
  sgst_inr numeric(14,2),
  igst_inr numeric(14,2),
  amount_inr numeric(14,2),
  reason text,
  created_by varchar,
  approved_by varchar,
  irn varchar
);
CREATE TABLE receipts (
  receipt_id int PRIMARY KEY,
  received_on date,
  channel varchar,
  method varchar,
  bank_account_id int REFERENCES bank_accounts,
  customer_id int REFERENCES customers,
  payer_name varchar,
  amount_inr numeric(14,2),
  tds_deducted_inr numeric(14,2),
  utr_reference varchar,
  remarks text,
  status varchar
);
CREATE TABLE receipt_allocations (
  allocation_id int PRIMARY KEY,
  receipt_id int REFERENCES receipts,
  invoice_id varchar REFERENCES invoices,
  amount_applied_inr numeric(14,2),
  tds_applied_inr numeric(14,2),
  allocated_by varchar,
  allocated_on date
);
CREATE TABLE gateway_settlements (
  settlement_id varchar PRIMARY KEY,
  gateway varchar,
  settlement_date date,
  gross_amount_inr numeric(14,2),
  fee_inr numeric(14,2),
  gst_on_fee_inr numeric(14,2),
  net_amount_inr numeric(14,2),
  settlement_utr varchar,
  payments_count int
);
CREATE TABLE gateway_settlement_items (
  settlement_id varchar REFERENCES gateway_settlements,
  receipt_id int REFERENCES receipts,
  gateway_txn_id varchar,
  amount_inr numeric(14,2)
);
CREATE TABLE cod_deposits (
  deposit_id int PRIMARY KEY,
  driver_id int REFERENCES drivers,
  deposited_on date,
  amount_inr numeric(14,2),
  bank_account_id int REFERENCES bank_accounts,
  bank_reference varchar
);
CREATE TABLE cod_collections (
  collection_id int PRIMARY KEY,
  order_id varchar REFERENCES orders,
  invoice_id varchar REFERENCES invoices,
  driver_id int REFERENCES drivers,
  amount_inr numeric(14,2),
  collected_on date,
  deposit_id int REFERENCES cod_deposits,
  receipt_id int REFERENCES receipts
);
CREATE TABLE payment_promises (
  promise_id int PRIMARY KEY,
  invoice_id varchar REFERENCES invoices,
  customer_id int REFERENCES customers,
  promised_amount_inr numeric(14,2),
  promised_date date,
  recorded_on date,
  recorded_by varchar,
  status varchar
);
CREATE TABLE collection_activities (
  activity_id int PRIMARY KEY,
  invoice_id varchar REFERENCES invoices,
  customer_id int REFERENCES customers,
  activity_date date,
  activity_type varchar,
  level int,
  done_by varchar,
  notes text
);
CREATE TABLE refunds (
  refund_id int PRIMARY KEY,
  order_id varchar REFERENCES orders,
  customer_id int REFERENCES customers,
  amount_inr numeric(14,2),
  reason varchar,
  ticket_id varchar,
  requested_by varchar,
  requested_on date,
  approved_by varchar,
  approved_on date,
  paid_on date,
  paid_via varchar
);
CREATE TABLE insurance_claims (
  claim_id int PRIMARY KEY,
  shipment_id int REFERENCES shipments,
  order_id varchar REFERENCES orders,
  insurer varchar,
  policy_no varchar,
  claim_amount_inr numeric(14,2),
  filed_on date,
  status varchar,
  settled_amount_inr numeric(14,2),
  settled_on date
);
CREATE TABLE shipment_finance (
  shipment_id int PRIMARY KEY REFERENCES shipments,
  order_id varchar,
  route varchar,
  distance_km int,
  declared_goods_value_inr numeric(14,2),
  fuel_cost_inr numeric(14,2),
  toll_cost_inr numeric(14,2),
  driver_cost_inr numeric(14,2),
  handling_cost_inr numeric(14,2),
  total_cost_inr numeric(14,2)
);
CREATE TABLE eway_bills (
  eway_bill_no varchar PRIMARY KEY,
  shipment_id int REFERENCES shipments,
  order_id varchar,
  goods_value_inr numeric(14,2),
  generated_on timestamptz,
  valid_until timestamptz,
  distance_km int
);
CREATE TABLE driver_daily_logs (
  log_id int PRIMARY KEY,
  driver_id int REFERENCES drivers,
  log_date date,
  vehicle_no varchar,
  vehicle_type varchar,
  hub varchar,
  deliveries_assigned int,
  delivered int,
  on_time int,
  km_driven int,
  fuel_litres numeric(14,2),
  toll_paid_cash numeric(14,2)
);
CREATE TABLE vendors (
  vendor_id int PRIMARY KEY,
  name varchar,
  category varchar,
  state varchar,
  pan varchar,
  gstin varchar,
  gst_rate_pct numeric(14,2),
  tds_section varchar,
  tds_rate_pct numeric(14,2),
  payment_terms_days int,
  msme_registered boolean,
  bank_account_no varchar,
  ifsc varchar,
  default_expense_account varchar,
  default_cost_centre varchar,
  po_required boolean,
  created_on date,
  created_by varchar,
  is_active boolean
);
CREATE TABLE vendor_bank_changes (
  change_id int PRIMARY KEY,
  vendor_id int REFERENCES vendors,
  old_account_no varchar,
  new_account_no varchar,
  old_ifsc varchar,
  new_ifsc varchar,
  requested_via varchar,
  requested_on date,
  changed_by varchar,
  changed_on date,
  approved_by varchar,
  approved_on date,
  verification_call_done boolean
);
CREATE TABLE purchase_orders (
  po_id varchar PRIMARY KEY,
  vendor_id int REFERENCES vendors,
  po_date date,
  total_inr numeric(14,2),
  status varchar,
  created_by varchar,
  approved_by varchar
);
CREATE TABLE po_lines (
  po_line_id int PRIMARY KEY,
  po_id varchar REFERENCES purchase_orders,
  line_no int,
  item varchar,
  quantity numeric(14,2),
  rate_inr numeric(14,2),
  amount_inr numeric(14,2)
);
CREATE TABLE goods_receipts (
  grn_id varchar PRIMARY KEY,
  po_id varchar REFERENCES purchase_orders,
  received_on date,
  received_by varchar,
  warehouse varchar
);
CREATE TABLE grn_lines (
  grn_line_id int PRIMARY KEY,
  grn_id varchar REFERENCES goods_receipts,
  po_line_no int,
  quantity_received numeric(14,2)
);
CREATE TABLE vendor_invoices (
  vendor_invoice_id int PRIMARY KEY,
  vendor_id int REFERENCES vendors,
  vendor_invoice_no varchar,
  invoice_date date,
  received_on date,
  po_id varchar REFERENCES purchase_orders,
  grn_id varchar REFERENCES goods_receipts,
  subtotal_inr numeric(14,2),
  cgst_inr numeric(14,2),
  sgst_inr numeric(14,2),
  igst_inr numeric(14,2),
  total_inr numeric(14,2),
  due_date date,
  expense_account varchar,
  cost_centre varchar,
  status varchar,
  file_name varchar,
  entered_by varchar,
  notes text
);
CREATE TABLE vendor_invoice_lines (
  vi_line_id int PRIMARY KEY,
  vendor_invoice_id int REFERENCES vendor_invoices,
  line_no int,
  item varchar,
  quantity numeric(14,2),
  rate_inr numeric(14,2),
  amount_inr numeric(14,2)
);
CREATE TABLE vendor_payments (
  payment_id int PRIMARY KEY,
  vendor_invoice_id int REFERENCES vendor_invoices,
  vendor_id int REFERENCES vendors,
  paid_on date,
  gross_settled_inr numeric(14,2),
  tds_deducted_inr numeric(14,2),
  tds_section varchar,
  amount_paid_inr numeric(14,2),
  mode varchar,
  bank_account_id int REFERENCES bank_accounts,
  paid_to_account_no varchar,
  utr_reference varchar,
  prepared_by varchar,
  approved_by varchar,
  approved_at timestamptz,
  notes text
);
CREATE TABLE vendor_statements (
  line_id int PRIMARY KEY,
  vendor_id int REFERENCES vendors,
  statement_date date,
  txn_date date,
  reference varchar,
  txn_type varchar,
  debit_inr numeric(14,2),
  credit_inr numeric(14,2),
  balance_inr numeric(14,2)
);
CREATE TABLE gstr2b_entries (
  entry_id int PRIMARY KEY,
  return_period varchar,
  supplier_gstin varchar,
  supplier_name varchar,
  invoice_no varchar,
  invoice_date date,
  taxable_value_inr numeric(14,2),
  cgst_inr numeric(14,2),
  sgst_inr numeric(14,2),
  igst_inr numeric(14,2),
  itc_available boolean
);
CREATE TABLE gst_returns (
  return_id int PRIMARY KEY,
  return_type varchar,
  period varchar,
  due_date date,
  filed_on date,
  status varchar,
  outward_taxable_inr numeric(14,2),
  output_tax_inr numeric(14,2),
  itc_claimed_inr numeric(14,2),
  cash_paid_inr numeric(14,2),
  arn varchar,
  prepared_by varchar
);
CREATE TABLE tds_challans (
  challan_id int PRIMARY KEY,
  period varchar,
  section varchar,
  tds_amount_inr numeric(14,2),
  interest_inr numeric(14,2),
  due_date date,
  paid_on date,
  challan_no varchar,
  bsr_code varchar
);
CREATE TABLE tds_returns (
  return_id int PRIMARY KEY,
  form varchar,
  quarter varchar,
  due_date date,
  filed_on date,
  status varchar,
  token_no varchar
);
CREATE TABLE tds_certificates_issued (
  cert_id int PRIMARY KEY,
  vendor_id int REFERENCES vendors,
  form varchar,
  quarter varchar,
  issued_on date
);
CREATE TABLE form26as_entries (
  entry_id int PRIMARY KEY,
  quarter varchar,
  deductor_name varchar,
  deductor_tan varchar,
  section varchar,
  amount_paid_inr numeric(14,2),
  tds_deposited_inr numeric(14,2),
  customer_id int REFERENCES customers
);
CREATE TABLE form16a_received (
  id int PRIMARY KEY,
  customer_id int REFERENCES customers,
  quarter varchar,
  tds_amount_inr numeric(14,2),
  received_on date
);
CREATE TABLE compliance_calendar (
  item_id int PRIMARY KEY,
  obligation varchar,
  due_date date,
  owner_employee_id varchar REFERENCES employees,
  status varchar
);
CREATE TABLE tax_notices (
  notice_id int PRIMARY KEY,
  authority varchar,
  notice_type varchar,
  period varchar,
  received_on date,
  reply_due date,
  amount_involved_inr numeric(14,2),
  issue text,
  status varchar,
  handled_by varchar
);
CREATE TABLE fixed_assets (
  asset_id int PRIMARY KEY,
  asset_tag varchar,
  asset_name varchar,
  category varchar,
  gl_account varchar,
  cost_centre varchar,
  location varchar,
  purchase_date date,
  cost_inr numeric(14,2),
  useful_life_years int,
  salvage_pct numeric(14,2),
  method varchar,
  status varchar,
  disposal_date date,
  sale_value_inr numeric(14,2),
  last_verified_on date,
  verification_status varchar
);
CREATE TABLE asset_depreciation (
  dep_id int PRIMARY KEY,
  asset_id int REFERENCES fixed_assets,
  period varchar,
  amount_inr numeric(14,2)
);
CREATE TABLE loans (
  loan_id int PRIMARY KEY,
  lender varchar,
  loan_type varchar,
  gl_account varchar,
  principal_inr numeric(14,2),
  interest_rate_pct numeric(5,2),
  start_date date,
  tenure_months int,
  emi_inr numeric(14,2),
  emi_day int,
  debit_account_id int REFERENCES bank_accounts,
  security varchar,
  covenant_min_dscr numeric(4,2),
  covenant_min_current_ratio numeric(4,2),
  covenant_max_debt_equity numeric(4,2),
  covenant_test varchar
);
CREATE TABLE loan_schedule (
  schedule_id int PRIMARY KEY,
  loan_id int REFERENCES loans,
  installment_no int,
  due_date date,
  emi_inr numeric(14,2),
  principal_inr numeric(14,2),
  interest_inr numeric(14,2),
  closing_balance_inr numeric(14,2),
  paid_on date,
  status varchar,
  penal_charges_inr numeric(14,2)
);
CREATE TABLE attendance_monthly (
  attendance_id int PRIMARY KEY,
  employee_id varchar REFERENCES employees,
  month varchar,
  working_days int,
  present_days int,
  paid_leave_days int,
  lop_days int,
  overtime_hours int,
  submitted_by varchar
);
CREATE TABLE payroll_runs (
  payroll_run_id int PRIMARY KEY,
  month varchar,
  status varchar,
  run_on date,
  prepared_by varchar,
  approved_by varchar,
  approved_on date,
  employees_count int,
  total_net_pay_inr numeric(14,2),
  payment_date date
);
CREATE TABLE payslips (
  payslip_id int PRIMARY KEY,
  payroll_run_id int REFERENCES payroll_runs,
  employee_id varchar REFERENCES employees,
  month varchar,
  fixed_gross_inr numeric(14,2),
  lop_deduction_inr numeric(14,2),
  earned_salary_inr numeric(14,2),
  overtime_hours_paid int,
  overtime_pay_inr numeric(14,2),
  incentive_inr numeric(14,2),
  gross_earned_inr numeric(14,2),
  pf_employee_inr numeric(14,2),
  esi_employee_inr numeric(14,2),
  professional_tax_inr numeric(14,2),
  tds_inr numeric(14,2),
  net_pay_inr numeric(14,2),
  pf_employer_inr numeric(14,2),
  esi_employer_inr numeric(14,2),
  paid_on date,
  bank_account_no varchar
);
CREATE TABLE expense_claims (
  claim_id int PRIMARY KEY,
  employee_id varchar REFERENCES employees,
  expense_date date,
  category varchar,
  amount_inr numeric(14,2),
  km_claimed int,
  description varchar,
  receipt_no varchar,
  submitted_on date,
  approved_by varchar,
  status varchar,
  reimbursed_on date
);
CREATE TABLE employee_advances (
  advance_id int PRIMARY KEY,
  employee_id varchar REFERENCES employees,
  given_on date,
  amount_inr numeric(14,2),
  purpose varchar,
  recovered_inr numeric(14,2),
  status varchar
);
CREATE TABLE credit_applications (
  application_id int PRIMARY KEY,
  applicant_name varchar,
  city varchar,
  gstin varchar,
  years_in_business int,
  annual_turnover_inr numeric(14,2),
  bureau_score int,
  requested_limit_inr numeric(14,2),
  trade_references int,
  existing_defaults int,
  submitted_on date,
  status varchar
);
CREATE TABLE customer_financials (
  id int PRIMARY KEY,
  customer_id int REFERENCES customers,
  fiscal_year varchar,
  revenue_inr numeric(14,2),
  net_profit_inr numeric(14,2),
  current_ratio numeric(4,2),
  received_on date
);
CREATE TABLE kyc_records (
  kyc_id int PRIMARY KEY,
  party_type varchar,
  party_id int,
  pan_verified boolean,
  gstin_verified boolean,
  bank_verified boolean,
  address_verified boolean,
  status varchar,
  verified_on date,
  verified_by varchar,
  next_review_due date
);
CREATE TABLE risk_register (
  risk_id int PRIMARY KEY,
  risk text,
  category varchar,
  likelihood varchar,
  impact varchar,
  owner_employee_id varchar,
  mitigation text,
  last_reviewed date
);
CREATE TABLE audit_findings (
  finding_id int PRIMARY KEY,
  audit varchar,
  area varchar,
  finding text,
  severity varchar,
  owner_employee_id varchar,
  due_date date,
  status varchar,
  closed_on date
);
CREATE TABLE erp_access_log (
  log_id int PRIMARY KEY,
  employee_id varchar REFERENCES employees,
  event_at timestamptz,
  event varchar,
  success boolean,
  ip_address varchar,
  location varchar
);
CREATE TABLE test_scenarios (
  scenario_id int PRIMARY KEY,
  role varchar,
  task varchar,
  table_name varchar,
  record_ref text,
  scenario text,
  expected_result text
);

