-- Handy views
CREATE VIEW v_trial_balance AS
  SELECT l.account_code, a.account_name, a.account_type, SUM(l.debit) AS total_debit, SUM(l.credit) AS total_credit,
         SUM(l.debit) - SUM(l.credit) AS balance_dr_cr
  FROM journal_lines l JOIN chart_of_accounts a USING (account_code) GROUP BY 1,2,3 ORDER BY 1;
CREATE VIEW v_invoice_balances AS
  SELECT i.invoice_id, i.customer_id, c.name AS customer_name, i.issued_on, i.due_on, i.amount_inr,
         COALESCE((SELECT SUM(amount_applied_inr + tds_applied_inr) FROM receipt_allocations a WHERE a.invoice_id = i.invoice_id), 0) AS applied_inr,
         COALESCE((SELECT SUM(amount_inr) FROM credit_notes n WHERE n.invoice_id = i.invoice_id), 0) AS credited_inr,
         i.status
  FROM invoices i JOIN customers c USING (customer_id);
COMMIT;
